# save transform to output bottom-left 8-connected component, check computed output
src='''def transform(grid):
    h,w=len(grid),len(grid[0]); pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]}
    comps=[]
    while pts:
        stack=[pts.pop()]; comp=set(stack)
        while stack:
            r,c=stack.pop()
            for dr in (-1,0,1):
                for dc in (-1,0,1):
                    q=(r+dr,c+dc)
                    if q in pts: pts.remove(q); comp.add(q); stack.append(q)
        comps.append(comp)
    comp=min((x for x in comps if min(r for r,c in x)>=14),key=lambda x:min(c for r,c in x))
    r0=min(r for r,c in comp); r1=max(r for r,c in comp); c0=min(c for r,c in comp); c1=max(c for r,c in comp)
    return [[grid[r][c] if (r,c) in comp else 0 for c in range(c0,c1+1)] for r in range(r0,r1+1)]
'''
